mapper.select:
SELECT @rownum:=@rownum+1 as num  ,a.*
from (SELECT @rownum:=0) r,(
select t.* from (







			UNION ALL





) t order by mdateUnadjust desc,IFNULL(adjustNum,0) desc
) a

select A.FINPROD_ID id, CONCAT_WS('',A.FINPROD_MARKET_ID ,':', A.FINPROD_ABBR) text
from FIN_PRODUCT A
inner join FIN_PRODUCT_ADD B
on A.FINPROD_ID = B.FINPROD_ID
and B.ISSUE_STATUS = #{ISSUE_STATUS01}
left join PTL_PORTFOLIO_AUTHORITY C

on B.PORTFOLIO_ID = C.PORTFOLIO_ID
where A.P_FINPROD_ID IS NULL

	and A.MDATE >= STR_TO_DATE(#{platDate},'%Y-%m-%d')

and A.FINPROD_TYPE2 = #{finprodType2}

	and (instr(A.FINPROD_MARKET_ID, #{search}) > 0 or instr(A.FINPROD_ABBR, #{search}) > 0)



		and A.FINPROD_ID = #{initValue}


		and C.USER_ID = #{userId}

select
IFNULL(T.MDATE, FIN_PRODUCT.MDATE) mdate , IFNULL(T.LDATE, FIN_PRODUCT.LIQUIDATION_DATE) ldateUnadjust , FIN_PRODUCT.FINPROD_ABBR finprodAbbr, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, IFNULL(T.adjustNum, 0) adjustNum, FIN_PRODUCT.VDATE vdate, FIN_PRODUCT.CALENDAR_ID calendarId, FIN_PRODUCT_ADD.DEAL_MODE dealMode, FIN_PRODUCT.PROFIT_TYPE profitType from FIN_PRODUCT
left join FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join (select FINPROD_ID, MDATE,LDATE,ADJUST_NUM adjustNum from PRD_MDATE_ADJUST where FINPROD_ID = #{finprodId} and ADJUST_NUM = ( SELECT MAX(T.ADJUST_NUM) FROM PRD_MDATE_ADJUST T WHERE T.FINPROD_ID = #{finprodId}) ) T on FIN_PRODUCT.FINPROD_ID = T.FINPROD_ID where FIN_PRODUCT.FINPROD_ID = #{finprodId}

select count(1) from TRD_FIN_PRODUCT_DEAL_TOTAL, FIN_PRODUCT
where TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
and TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2 = #{finprodType2}
and FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2}
and FIN_PRODUCT.FINPROD_ID = #{finprodId}
and TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_DATE >= STR_TO_DATE(#{mdate}, '%Y-%m-%d')
and TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_STATUS = #{tradeStatus}

select IFNULL(max(adjust_num),0) adjustNum
from PRD_MDATE_ADJUST
where FINPROD_ID=#{finprodId}

mapper.sql:
select FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, NULL AS adjusttype, FIN_PRODUCT.MDATE mdateUnadjust, FIN_PRODUCT.LIQUIDATION_DATE ldateUnadjust, NULL AS ldate, NULL AS bdate, NULL AS rdate, NULL AS mdate, NULL AS remark, FIN_PRODUCT.FINPROD_ID finprodId, NULL AS adjustNum, NULL AS status, PMSI.SEND_STATUS sendStatus, PMSI.SEND_REMARK sendRemark from FIN_PRODUCT_ADD, PTL_PORTFOLIO_AUTHORITY, FIN_PRODUCT LEFT JOIN INF_PRD_MDATE_ADJUST PMSI ON FIN_PRODUCT.FINPROD_ID = PMSI.FINPROD_ID where FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId} and FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2} and FIN_PRODUCT.P_FINPROD_ID IS NULL and date_format(FIN_PRODUCT.MDATE, '%Y-%m-%d %H%-%i-%s') >= #{platDate} and FIN_PRODUCT_ADD.ISSUE_STATUS = #{ISSUE_STATUS01}
and FIN_PRODUCT.FINPROD_ID IN
#{item}
AND IFNULL(PMSI.SEND_STATUS, '03') = #{sendStatus,jdbcType=VARCHAR}
and not exists (select 1 from PRD_MDATE_ADJUST where FIN_PRODUCT.FINPROD_ID = PRD_MDATE_ADJUST.FINPROD_ID)

select FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, PRD_MDATE_ADJUST.ADJUST_TYPE adjusttype, PRD_MDATE_ADJUST.MDATE_UNADJUST mdateUnadjust, PRD_MDATE_ADJUST.LDATE_UNADJUST ldateUnadjust,
PRD_MDATE_ADJUST.LDATE ldate, (CASE WHEN PRD_MDATE_ADJUST.ADJUST_TYPE = #{TZLX_TQZZ} THEN PRD_MDATE_ADJUST.MDATE ELSE NULL END) bdate,
(CASE WHEN PRD_MDATE_ADJUST.ADJUST_TYPE = #{TZLX_CPZQ} THEN PRD_MDATE_ADJUST.MDATE ELSE NULL END) rdate,
(CASE WHEN PRD_MDATE_ADJUST.ADJUST_TYPE = #{TZLX_DQRTZ} THEN PRD_MDATE_ADJUST.MDATE ELSE NULL END) mdate,
PRD_MDATE_ADJUST.REMARK remark, FIN_PRODUCT.FINPROD_ID finprodId, PRD_MDATE_ADJUST.ADJUST_NUM adjustNum, (CASE WHEN PRD_MDATE_ADJUST.ADJUST_NUM = (select max(ADJUST_NUM) from PRD_MDATE_ADJUST pma where pma.FINPROD_ID=PRD_MDATE_ADJUST.FINPROD_ID) THEN 'E' ELSE 'D' END) status,
PMSI.SEND_STATUS sendStatus, PMSI.SEND_REMARK sendRemark from PRD_MDATE_ADJUST, FIN_PRODUCT_ADD, PTL_PORTFOLIO_AUTHORITY, FIN_PRODUCT LEFT JOIN INF_PRD_MDATE_ADJUST PMSI ON FIN_PRODUCT.FINPROD_ID = PMSI.FINPROD_ID where FIN_PRODUCT.FINPROD_ID = PRD_MDATE_ADJUST.FINPROD_ID and FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
and FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId} and FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2} and FIN_PRODUCT_ADD.ISSUE_STATUS = #{ISSUE_STATUS01}
and FIN_PRODUCT.FINPROD_ID IN
#{item}
and PRD_MDATE_ADJUST.MDATE >= STR_TO_DATE(#{adjustAfterMdateStart}, '%Y-%m-%d')
and PRD_MDATE_ADJUST.MDATE <= STR_TO_DATE(#{adjustAfterMdateEnd}, '%Y-%m-%d')
and PRD_MDATE_ADJUST.ADJUST_TYPE = #{adjustType}
AND IFNULL(PMSI.SEND_STATUS, '03') = #{sendStatus,jdbcType=VARCHAR}
